  shutil.copyfile(ROOT/'tools/web/lfo-destinations.js',out/'lfo-destinations.js');(out/'lfo-destinations-data.js').write_text('window.MCLfoDestinations='+json.dumps(data,separators=(',',':'))+';\n',encoding='utf-8')
  s=(out/'index.html').read_text(encoding='utf-8');s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s);s=s.replace('../assets/release.js?','test-release.js?').replace('909-release.js?','test-release.js?')
  notice='<p><strong data-l="en">LFO destination / quick-assign test — '+edition+'.</strong><strong data-l="fr">Test destinations LFO et assignation rapide — '+edition+'.</strong> <span data-l="en">Retrosyn controls: Timbre / Oscillator / Pitch Sweep / Chord Arp. Look for ATK (Attack), FLT (Cutoff) and RES (Resonance) in either audio LFO. Keep LFO held, then hold MACHINES: the LFO screen stays visible. Turn DECAY / SWEEP / CONTOUR to assign Attack / Cutoff / Resonance; turn again on the assigned target to adjust depth. On the LFO 2 page the gesture assigns LFO 2. Both LFO menus stay open after quick assign. Attack is included in the destination picker. Sample Wizard uses its native Filter / Resonance destinations for SWEEP / CONTOUR, with or without MACHINES; other machines keep separate Sweep / Contour and MACHINES + Filter / Resonance targets. MACHINES-modified knob actions return to the main track screen after the popup, without leaving the machine selector behind. CPU/CUT diagnostics included: main needs Beat Repeat and a SY engine selected; 909 enables the diagnostic automatically. Release TRACK + RETRIG to see the readings. Audio processing is unchanged. Released flashers unchanged.</span><span data-l="fr">Controles Retrosyn : Timbre / Oscillator / Pitch Sweep / Chord Arp. ATK (attaque), FLT (coupure) et RES (resonance) dans les deux LFO audio. Tenir LFO puis MACHINES : le menu LFO reste visible. Tourner DECAY / SWEEP / CONTOUR pour assigner attaque / coupure / resonance ; tourner encore sur la cible assignee ajuste la profondeur. Dans la page LFO2, le geste assigne LFO2. Les deux menus LFO restent ouverts apres assignation rapide. Attack figure dans le selecteur. Sample Wizard utilise ses destinations natives filtre / resonance sur SWEEP / CONTOUR avec ou sans MACHINES ; les autres machines gardent leurs cibles distinctes. Les gestes avec MACHINES ferment le selecteur sous-jacent : retour a la piste apres le popup. Diagnostics CPU/CUT inclus : principal avec Beat Repeat et moteur SY ; actives automatiquement dans909. Relacher TRACK + RETRIG pour les mesures. Traitement audio conserve ; versions publiees inchangees.</span></p>'
  if source!='flasher':notice=notice.replace('Retrosyn controls: Timbre / Oscillator / Pitch Sweep / Chord Arp. ','').replace('Controles Retrosyn : Timbre / Oscillator / Pitch Sweep / Chord Arp. ','')
  s=s.replace('<main class="wrap fl">','<main class="wrap fl">'+notice).replace('</body>',''.join(f'<script src="{name}?v={STAMP}"></script>' for name in ('beat-diagnostic-data.js','beat-diagnostic.js','lfo-destinations-data.js','lfo-destinations.js'))+'</body>');(out/'index.html').write_text(s,encoding='utf-8')
  (out/'test-release.js').write_text('window.MC_RELEASES='+json.dumps([dict(version='LFO-destinations-test.7',date='2026-10-18',changes=[dict(en='Explicit ATK / FLT / RES destinations and LFO + MACHINES quick assign. Test only with CPU/CUT diagnostics. Audio routines unchanged.',fr='Destinations ATK / FLT / RES et assignation LFO + MACHINES. Test avec diagnostics CPU/CUT. Routines audio conservees.')])])+';\n',encoding='utf-8')
  (out/'BUILD.json').write_text(json.dumps(dict(stamp=STAMP,base=edition,scope='test-only',diagnostics=True,audio_unchanged=True,released_flashers_unchanged=True),indent=2)+'\n',encoding='utf-8')
  if a.check:
   for f in out.iterdir():assert f.read_bytes().replace(b'\r\n',b'\n')==(folder/f.name).read_bytes().replace(b'\r\n',b'\n'),str(f)
